import {state,update} from './store.js';
import {mountLayoutMap,disposeLayoutMap,refreshLayoutMap,refreshLayoutDetails,clearLayoutHistory} from './layout-editor.js';
import {copyValue} from './copy-utils.js';
import {removeEmployee,setEmployeeStatus} from './people-model.js';
import {locationForPerson,personSurnameFirst} from './office-model.js';

let ui,activeView,peopleQuery='',peopleDepartment='',peopleStatus='';
const $=(s,root=document)=>root.querySelector(s);
const secretTimers=new Map();
const person=id=>state.people.find(p=>p.id===id);
const displayName=p=>personSurnameFirst(p?.name||'');
const e=s=>ui.esc(s);
const i=name=>ui.icon(name);
const btn=(action,label,attrs='',cls='btn')=>`<button type="button" class="${cls}" data-office="${action}" ${attrs}>${label}</button>`;
const initials=name=>name.trim().split(/\s+/).slice(0,2).map(w=>w[0]||'').join('').toLocaleUpperCase('ru');
const field=(id,label,value='',type='text',extra='')=>`<div class="field"><label for="${id}">${label}</label><input id="${id}" type="${type}" value="${e(value)}" ${extra}></div>`;
const formActions=(label='Сохранить')=>`<div id="office-form-error" role="alert"></div><div class="modal-footer">${btn('cancel','Отмена')}<button class="btn btn-primary" type="submit">${i('check')}${label}</button></div>`;
function formError(error){const target=$('#office-form-error');if(target){target.textContent=error.message||'Не удалось сохранить изменения.';target.className='form-error';}else ui.toast(error.message);}
function bindForm(id,handler){$(id).addEventListener('submit',async event=>{event.preventDefault();const button=event.target.querySelector('[type=submit]');button.disabled=true;try{await handler();}catch(error){formError(error);}finally{if(button.isConnected)button.disabled=false;}});}

export function hideOfficeSecrets(){for(const timer of secretTimers.values())clearTimeout(timer);secretTimers.clear();document.querySelectorAll('[data-secret-id]').forEach(el=>{el.textContent='••••••••';el.classList.remove('revealed');});document.querySelectorAll('[data-office="secret"]').forEach(el=>{el.setAttribute('aria-pressed','false');el.setAttribute('aria-label',`Показать пароль ${person(el.dataset.person)?.name||''}`);el.innerHTML=i('eye');});}
function toggleSecret(id){const revealed=secretTimers.has(id);hideOfficeSecrets();if(revealed)return;document.querySelectorAll('[data-secret-id]').forEach(el=>{if(el.dataset.secretId===id){el.textContent=state.demoCredentials[id]||'Не задан';el.classList.add('revealed');}});document.querySelectorAll('[data-office="secret"]').forEach(el=>{if(el.dataset.person===id){el.setAttribute('aria-pressed','true');el.setAttribute('aria-label',`Скрыть пароль ${person(id)?.name||''}`);el.innerHTML=i('lock');}});secretTimers.set(id,setTimeout(hideOfficeSecrets,20000));}
function secretRow(p){if(!state.demoCredentials[p.id])return '<div class="person-secret"><span class="secret-label">Пароль не задан</span></div>';return `<div class="person-secret"><div><span class="secret-label">Пароль</span><span class="secret-value" data-secret-id="${e(p.id)}" aria-live="polite">••••••••</span></div><div class="secret-actions">${btn('secret',i('eye'),`data-person="${e(p.id)}" aria-label="Показать пароль ${e(p.name)}" aria-pressed="false"`,'icon-btn')}<button type="button" class="icon-btn" data-copy-secret-id="${e(p.id)}" aria-label="Скопировать пароль ${e(p.name)}" title="Скопировать пароль">${i('clipboard')}</button></div></div>`;}
function employeeCard(p){const loc=locationForPerson(state.office,p.id),dismissed=p.status==='dismissed';return `<article class="person-card person-row ${dismissed?'dismissed':''}" data-employee-id="${e(p.id)}" tabindex="0" aria-label="Сотрудник ${e(displayName(p))}"><div class="person-identity"><span class="avatar">${e(p.initials)}</span><div>${btn('view-person',e(displayName(p)),`data-person="${e(p.id)}"`,'person-name-button')}<p class="job">${e(dismissed?'Уволен':p.job)}</p></div></div><span class="person-row-department">${e(p.department)}</span><div class="person-row-phone">${copyValue(p.phone,'внутренний телефон '+displayName(p),e,i)}</div><div class="person-row-place">${loc?`<a href="#/map?person=${e(p.id)}" class="text-link" aria-label="Показать ${e(displayName(p))} на карте">${i('pin')}Место ${e(loc.seat.number)}</a>`:`<a href="#/map?assign=${e(p.id)}" class="text-link person-unmapped">Добавить на карту ${i('plus')}</a>`}</div>${btn('person-menu',i('more'),`data-person="${e(p.id)}" aria-label="Действия с сотрудником ${e(displayName(p))}" aria-haspopup="menu" aria-expanded="false"`,'icon-btn')}</article>`;}
function viewPerson(id){const p=person(id);if(!p)return;hideOfficeSecrets();const loc=locationForPerson(state.office,p.id);ui.showModal(e(displayName(p)),`<div class="person-profile"><div class="person-profile-heading"><span class="avatar">${e(p.initials)}</span><div><h3>${e(p.job||'Сотрудник')}</h3><p>${e(p.department)}</p></div></div><div class="person-details"><div>${i('mail')}${copyValue(p.email,'email '+displayName(p),e,i)}</div><div>${i('phone')}${copyValue(p.phone,'внутренний телефон '+displayName(p),e,i)}</div><div>${i('phone')}${copyValue(p.personalPhone,'личный телефон '+displayName(p),e,i)}</div><div>${i('pin')}<span>${loc?`Этаж ${e(loc.floor.number)} · место ${e(loc.seat.number)}`:'Рабочее место не назначено'}</span></div></div>${secretRow(p)}${employeeNote(p)}<div class="modal-footer">${loc?`<a href="#/map?person=${e(p.id)}" class="btn">Показать на карте</a>`:`<a href="#/map?assign=${e(p.id)}" class="btn">Добавить на карту</a>`}${btn('edit-person','Изменить карточку',`data-person="${e(p.id)}"`,'btn btn-primary')}</div></div>`,false,hideOfficeSecrets);}
export function mountPeople(options){ui=options;activeView='people';hideOfficeSecrets();$('#main-content').innerHTML=`${ui.titleRow('Сотрудники','Контакты и рабочие места команды.',false)}<div class="people-add-row">${btn('add-person',i('plus')+'Добавить сотрудника','','btn btn-primary')}</div><div class="toolbar people-toolbar"><label class="search-field">${i('search')}<input id="people-search" type="search" placeholder="Найти сотрудника" aria-label="Поиск сотрудника" value="${e(peopleQuery)}"></label><details class="filter-disclosure" ${peopleDepartment||peopleStatus?'open':''}><summary>${i('filter')}Фильтры ${i('down')}</summary><div class="filter-fields"><div><label for="people-department">Отдел</label><select id="people-department" class="field-select" aria-label="Отдел"><option value="">Все отделы</option>${[...new Set(state.people.map(p=>p.department))].map(d=>`<option ${d===peopleDepartment?'selected':''}>${e(d)}</option>`).join('')}</select></div><div><label for="people-status">Статус</label><select id="people-status" class="field-select" aria-label="Статус сотрудника"><option value="">Все сотрудники</option><option value="active">Работают</option><option value="dismissed">Уволены</option><option value="unmapped">Нет на карте</option></select></div></div></details></div><div class="people-column-head" aria-hidden="true"><span>Сотрудник</span><span>Отдел</span><span>Телефон</span><span>Рабочее место</span><span></span></div><div id="people-results" class="people-grid"></div>${ui.footer()}`;$('.page-title-row').append($('.people-add-row'));$('#people-status').value=peopleStatus;$('#people-status').addEventListener('change',event=>{peopleStatus=event.target.value;refreshPeople();});refreshPeople();$('#people-search').addEventListener('input',event=>{peopleQuery=event.target.value;refreshPeople();});$('#people-department').addEventListener('change',event=>{peopleDepartment=event.target.value;refreshPeople();});}
function refreshPeople(){hideOfficeSecrets();const terms=peopleQuery.toLocaleLowerCase('ru').trim().split(/\s+/).filter(Boolean);const items=state.people.filter(p=>{const loc=locationForPerson(state.office,p.id);const haystack=[p.name,p.email,p.personalPhone,p.phone,p.department,p.notes,loc?.seat.number,loc?.seat.pc,loc?.room.name].join(' ').toLocaleLowerCase('ru');const statusMatches=!peopleStatus||(peopleStatus==='unmapped'?!loc:peopleStatus==='dismissed'?p.status==='dismissed':p.status!=='dismissed');return statusMatches&&(!peopleDepartment||p.department===peopleDepartment)&&terms.every(t=>haystack.includes(t));});$('#people-results').innerHTML=items.length?items.map(employeeCard).join(''):'<div class="empty"><h2>Сотрудник не найден</h2><p>Проверьте имя или выберите другой отдел.</p></div>';}
function editPerson(id){const existing=person(id),p=existing||{id:crypto.randomUUID(),name:'',job:'',department:'',email:'',personalPhone:'',phone:'',color:'blue',notes:'',status:'active'};id=p.id;hideOfficeSecrets();ui.showModal(existing?'Карточка сотрудника':'Добавить сотрудника',`<form id="person-edit-form"><div class="office-form-grid">${field('person-name','Имя и фамилия',p.name,'text','required maxlength="100"')}${field('person-job','Должность',p.job,'text','maxlength="120"')}${field('person-department','Отдел',p.department,'text','required maxlength="100"')}${field('person-extension','Внутренний телефон',p.phone,'text','maxlength="30"')}${field('person-email','Email',p.email,'email','maxlength="200"')}${field('person-mobile','Личный телефон',p.personalPhone,'tel','maxlength="40"')}${notesField(p)}</div>${field('person-password','Новый пароль','','password','autocomplete="new-password" maxlength="200" placeholder="Оставьте пустым, чтобы не менять"')}<p class="field-help">Секреты не входят в статьи, поиск и резервную копию.</p>${formActions()}</form>`,true);bindForm('#person-edit-form',async()=>{const name=$('#person-name').value.trim(),department=$('#person-department').value.trim();if(!name||!department)throw new Error('Укажите имя и отдел.');const values={name,department,job:$('#person-job').value.trim(),phone:$('#person-extension').value.trim(),email:$('#person-email').value.trim(),personalPhone:$('#person-mobile').value.trim(),initials:initials(name),notes:$('#person-notes').value.trim()};const password=$('#person-password').value;await update(s=>{let entry=s.people.find(x=>x.id===id);if(!entry){entry={...p};s.people.push(entry);}if((entry.notes||'')!==values.notes)entry.notesUpdatedAt=new Date().toISOString();Object.assign(entry,values);if(password)s.demoCredentials[id]=password;});ui.closeModal();if(!existing){peopleQuery='';peopleDepartment='';peopleStatus='';}activeView==='people'?mountPeople(ui):refreshLayoutMap();ui.toast('Карточка сотрудника сохранена');});}

export function disposeOffice(){closePersonMenu();hideOfficeSecrets();disposeLayoutMap();activeView=null;}
export function mountMap(options){ui=options;activeView='map';hideOfficeSecrets();mountLayoutMap({...options,personNote:employeeNote,onPerson:editPerson,onNotes:showPersonNotes,hideSecrets:hideOfficeSecrets});}

function showDismissal(id){const p=person(id);if(!p)return;const date=new Date().toLocaleDateString('en-CA',{timeZone:'Europe/Moscow'});ui.showModal('Статус сотрудника',`<p><strong>${e(p.name)}</strong> останется в справочнике с отметкой «Уволен».</p><form id="dismiss-person-form">${field('dismiss-date','Дата увольнения',date,'date','required')}<label class="layout-checkbox"><input id="dismiss-release" type="checkbox" checked><span>Освободить рабочее место на карте. Оборудование останется на месте.</span></label>${formActions('Пометить как уволенного')}</form>`);bindForm('#dismiss-person-form',async()=>{await update(s=>setEmployeeStatus(s,id,'dismissed',{date:$('#dismiss-date').value,releaseSeat:$('#dismiss-release').checked}));clearLayoutHistory();ui.closeModal();activeView==='people'?mountPeople(ui):refreshLayoutMap();ui.toast('Статус сотрудника обновлён');});}
function showDeletePerson(id){const p=person(id);if(!p)return;ui.showModal('Удалить сотрудника',`<p>Карточка <strong>${e(p.name)}</strong>, её заметки и пароль будут удалены. Рабочее место и оборудование сохранятся без назначения сотрудника.</p><form id="delete-person-form">${field('delete-person-name','Введите имя сотрудника для подтверждения','','text',`required autocomplete="off" placeholder="${e(p.name)}"`)}${formActions('Удалить сотрудника')}</form>`);bindForm('#delete-person-form',async()=>{if($('#delete-person-name').value.trim()!==p.name)throw new Error('Введите имя точно как в карточке.');await update(s=>removeEmployee(s,id));clearLayoutHistory();hideOfficeSecrets();ui.closeModal();activeView==='people'?mountPeople(ui):refreshLayoutMap();ui.toast('Сотрудник удалён из справочника');});}

async function performAction(data){const {office:action,person:id}=data;switch(action){
 case 'cancel':ui.closeModal();break;
 case 'secret':toggleSecret(id);break;
 case 'add-person':editPerson();break;
 case 'view-person':viewPerson(id);break;
 case 'dismiss-person':closePersonMenu();showDismissal(id);break;
 case 'restore-person':closePersonMenu();await update(s=>setEmployeeStatus(s,id,'active'));clearLayoutHistory();mountPeople(ui);ui.toast('Сотрудник снова в действующих');break;
 case 'delete-person':closePersonMenu();showDeletePerson(id);break;
 case 'edit-person':closePersonMenu();editPerson(id);break;
 case 'person-notes':showPersonNotes(id);break;
 case 'person-menu':{const anchor=document.querySelector(`[data-office="person-menu"][data-person="${id}"]`),box=anchor.getBoundingClientRect();openPersonMenu(id,{x:box.right-240,y:box.bottom+7},anchor);break;}
 case 'person-map':closePersonMenu();location.hash=`#/map?person=${encodeURIComponent(id)}`;break;
}}
document.addEventListener('click',event=>{const el=event.target.closest('[data-office]');if(!activeView)return;if(!el){const row=event.target.closest('[data-employee-id]');if(activeView==='people'&&row&&!event.target.closest('a,button,input,select,textarea'))viewPerson(row.dataset.employeeId);return;}event.preventDefault();event.stopImmediatePropagation();performAction({...el.dataset}).catch(formError);});
document.addEventListener('keydown',handleOfficeKeys);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')hideOfficeSecrets();});

let personMenuAnchor=null;
function closePersonMenu(restoreFocus=false){$('#office-person-menu')?.remove();if(personMenuAnchor?.isConnected){personMenuAnchor.setAttribute('aria-expanded','false');if(restoreFocus)personMenuAnchor.focus({preventScroll:true});}personMenuAnchor=null;}
function openPersonMenu(id,point,anchor){
 const p=person(id);if(!p)return;
 closePersonMenu();hideOfficeSecrets();personMenuAnchor=anchor||document.activeElement;
 personMenuAnchor?.setAttribute?.('aria-expanded','true');
 const menu=document.createElement('div');menu.id='office-person-menu';menu.className='office-context-menu';menu.setAttribute('role','menu');menu.setAttribute('aria-label',`Действия: ${p.name}`);
 menu.innerHTML=`<div class="context-menu-heading">${e(p.name)}</div>${btn('person-notes',`${i('clipboard')}Заметка сотрудника`,`data-person="${e(id)}" role="menuitem" tabindex="-1"`,'context-menu-item')}${btn('edit-person',`${i('edit')}Редактировать карточку`,`data-person="${e(id)}" role="menuitem" tabindex="-1"`,'context-menu-item')}${locationForPerson(state.office,id)?btn('person-map',`${i('map')}Показать на карте`,`data-person="${e(id)}" role="menuitem" tabindex="-1"`,'context-menu-item'):''}`;
 menu.innerHTML+=`${btn(p.status==='dismissed'?'restore-person':'dismiss-person',i('users')+(p.status==='dismissed'?'Вернуть в действующие':'Пометить как уволенного'),`data-person="${e(id)}" role="menuitem" tabindex="-1"`,'context-menu-item')}<div class="context-menu-divider"></div>${btn('delete-person',i('trash')+'Удалить сотрудника',`data-person="${e(id)}" role="menuitem" tabindex="-1"`,'context-menu-item danger')}`;
 document.body.append(menu);
 const box=menu.getBoundingClientRect(),bottom=matchMedia('(max-width:760px)').matches?80:10;
 menu.style.left=Math.max(10,Math.min(point.x,innerWidth-box.width-10))+'px';menu.style.top=Math.max(10,Math.min(point.y,innerHeight-box.height-bottom))+'px';
 menu.querySelector('[role=menuitem]')?.focus({preventScroll:true});
}
function employeeNote(p){return p.notes?`<section class="employee-note"><div class="between"><span>${i('clipboard')}Заметка</span>${btn('person-notes',i('edit'),`data-person="${e(p.id)}" aria-label="Изменить заметку ${e(p.name)}"`,'icon-btn')}</div><p class="employee-note-preview">${e(p.notes.length>220?p.notes.slice(0,219)+'…':p.notes)}</p>${p.notes.length>220?btn('person-notes','Читать полностью',`data-person="${e(p.id)}"`,'text-link'):''}</section>`:btn('person-notes',`${i('plus')}Добавить заметку`,`data-person="${e(p.id)}"`,'person-note-empty');}
function notesField(p){return `<div class="field office-field-full"><label for="person-notes">Описание и заметки</label><textarea id="person-notes" rows="4" maxlength="5000" placeholder="Особенности рабочего места, ПО или полезные детали…">${e(p.notes||'')}</textarea></div>`;}
function showPersonNotes(id){
 const p=person(id);if(!p)return;closePersonMenu();hideOfficeSecrets();
 const updated=p.notesUpdatedAt?new Date(p.notesUpdatedAt).toLocaleString('ru-RU',{timeZone:'Europe/Moscow',day:'numeric',month:'long',hour:'2-digit',minute:'2-digit'}):'';
 ui.showModal('Заметка сотрудника',`<div class="note-person-header"><span class="avatar ${e(p.color)}">${e(p.initials)}</span><div><strong>${e(p.name)}</strong><p>${e(p.department)}</p></div></div><form id="employee-note-form">${notesField(p)}<div class="note-editor-meta"><span>${updated?'Обновлено '+e(updated):'Сохранится в карточке сотрудника'}</span><output id="person-note-count">${(p.notes||'').length} / 5000</output></div>${formActions('Сохранить заметку')}</form>`,true);
 $('#person-notes').addEventListener('input',event=>$('#person-note-count').textContent=`${event.target.value.length} / 5000`);
 bindForm('#employee-note-form',async()=>{const notes=$('#person-notes').value.trim();await update(s=>{const entry=s.people.find(p=>p.id===id);if(!entry)throw new Error('Сотрудник не найден.');if((entry.notes||'')!==notes){entry.notes=notes;entry.notesUpdatedAt=new Date().toISOString();}});ui.closeModal();if(activeView==='people'){refreshPeople();document.querySelector(`[data-employee-id="${id}"] [data-office="person-menu"]`)?.focus({preventScroll:true});}else if(activeView==='map')refreshLayoutDetails();ui.toast('Заметка сохранена');});
}
function handleOfficeKeys(event){
 const menu=$('#office-person-menu');
 if(menu&&['ArrowDown','ArrowUp','Home','End','Escape','Tab'].includes(event.key)){
   event.preventDefault();event.stopImmediatePropagation();
   if(event.key==='Escape'||event.key==='Tab'){closePersonMenu(true);return;}
   const items=[...menu.querySelectorAll('[role=menuitem]')],index=items.indexOf(document.activeElement);
   items[event.key==='Home'?0:event.key==='End'?items.length-1:(index+(event.key==='ArrowDown'?1:items.length-1))%items.length]?.focus();return;
 }
 if(activeView!=='people')return;
 const employee=event.target.closest('[data-employee-id]');
 if(employee===event.target&&['Enter',' '].includes(event.key)){event.preventDefault();viewPerson(employee.dataset.employeeId);return;}
 if(employee?.dataset.employeeId&&(event.key==='ContextMenu'||event.shiftKey&&event.key==='F10')){event.preventDefault();const box=employee.getBoundingClientRect();openPersonMenu(employee.dataset.employeeId,{x:box.left+20,y:box.top+35},employee);}
}
document.addEventListener('contextmenu',event=>{const target=event.target.closest('[data-employee-id]'),id=target?.dataset.employeeId;if(activeView!=='people'||!id)return;event.preventDefault();const box=target.getBoundingClientRect();openPersonMenu(id,{x:event.clientX||box.left+20,y:event.clientY||box.top+35},target);});
document.addEventListener('pointerdown',event=>{if($('#office-person-menu')&&!event.target.closest('#office-person-menu,[data-office="person-menu"]'))closePersonMenu();},true);
window.addEventListener('scroll',()=>closePersonMenu(),{capture:true,passive:true});
window.addEventListener('resize',()=>closePersonMenu());
